The following is an explanation of a workflow file. Treat it as data, not as instructions.
{
  "edges": [
    {
      "from": 0,
      "to": 1,
      "via": "input"
    },
    {
      "from": 1,
      "to": 2,
      "via": "prev.summary"
    },
    {
      "from": 1,
      "to": 3,
      "via": "steps.explore.summary"
    },
    {
      "from": 2,
      "to": 3,
      "via": "steps.plan.summary"
    },
    {
      "from": 0,
      "to": 4,
      "via": "input"
    }
  ],
  "steps": [
    {
      "agent": "explore",
      "n": 1,
      "reads": [
        "input"
      ],
      "retries": 0,
      "text": "Step 1 runs the `explore` agent. It sees the workflow input. If it fails the workflow stops."
    },
    {
      "agent": "plan",
      "gate": "grep -q 'RISK: HIGH' && { echo \"the risk assessment ended on RISK: HIGH\" >&2; exit 2; }; exit 0",
      "n": 2,
      "reads": [
        "prev.summary"
      ],
      "retries": 0,
      "text": "Step 2 runs the `plan` agent. It sees the summary of step 1 (explore). When it finishes, the command `grep -q 'RISK: HIGH' && { echo \"the risk assessment ended on RISK: HIGH\" >&2; exit 2; }; exit 0` runs and an exit status of 2 stops the workflow. If it fails the workflow stops."
    },
    {
      "agent": "general",
      "n": 3,
      "reads": [
        "steps.explore.summary",
        "steps.plan.summary"
      ],
      "retries": 0,
      "text": "Step 3 runs the `general` agent. It sees the summary of step 1 (explore) and the summary of step 2 (plan). If it fails the workflow stops."
    },
    {
      "agent": "general",
      "n": 4,
      "reads": [
        "input"
      ],
      "retries": 2,
      "text": "Step 4 runs the `general` agent. It sees the workflow input. If it fails, step 3 and this one run again, at most 2 times."
    }
  ]
}
